Tool response:
Tool: find_nearby_tire_centers
Description: Find Nearby Tire Centers
Parameters:
    {
      "type": "object",
      "properties": {
        "location_name": {
          "type": "string",
          "description": "Name of the reference location",
          "title": "Location Name"
        },
        "service_name": {
          "type": "string",
          "description": "Name of the service to filter by",
          "title": "Service Name"
        },
        "max_distance_miles": {
          "type": "number",
          "description": "Maximum distance in miles",
          "default": 5.0,
          "title": "Max Distance Miles"
        }
      },
      "required": [
        "location_name",
        "service_name"
      ]
    }
